                <label className="pc-toggle"><input type="checkbox" disabled={!data.capabilities.websiteManage} checked={siteForm.publicFeedEnabled} onChange={(event) => setSiteForm({ ...siteForm, publicFeedEnabled: event.target.checked })} /><span><strong>Enable public content feed</strong><small>Allows the configured business website to read approved published pages. Drafts remain private.</small></span></label>
